//! 简体中文文案（默认语言，也是所有缺失键的最终兜底）。
//!
//! 约定：
//! - 键名 `区域.语义`，同一区域集中在此处，便于整体审校；
//! - 参数用 `{name}`，由 `translate()` 统一插值；
//! - 复数变体为 `键_one` / `键_other`，由 Intl.PluralRules 选择（中文两者通常相同）；
//! - 用户输入内容（任务标题、笔记、文件名、剪贴板正文）**不得**进入本文件。

