  "taskAnalytics.priority.title": "优先级分布",
  "taskAnalytics.priority.hint": "完成数量",
  "taskAnalytics.priority.p0": "P0 紧急",
  "taskAnalytics.priority.p1": "P1 高",
  "taskAnalytics.priority.p2": "P2 中",
  "taskAnalytics.priority.p3": "P3 低",
  "taskAnalytics.definitions.title": "指标口径",
  "taskAnalytics.definitions.completed": "完成数量：范围内真实发生的完成动作。普通任务每次勾选完成记 1 次；重复任务每完成一期记 1 次（任务本身保持未完成并推进到下一期）；同一任务的同一期次只计 1 次。",
  "taskAnalytics.definitions.completionRate": "完成率 = 本期到期任务中已完成的数量 / 本期到期任务数。分母含本期尚未到期的任务，因此本期未结束时它是「当前进度」而不是最终结果。",
  "taskAnalytics.definitions.overdueRate": "逾期率 = 本期到期任务中逾期的数量 / 本期到期任务数。逾期指：完成时间晚于截止时间，或仍未完成且截止时间已过（本期尚未到期的任务不算逾期）。",
  "taskAnalytics.definitions.trend": "趋势按本地日历分桶：日视图近 14 天、周视图近 12 周（周一为一周起点）、月视图近 12 个月。完成与逾期同为计数，共用刻度。",
  "taskAnalytics.definitions.distribution": "分类 / 优先级分布按「完成事件发生时的快照」统计；分类为空显示为「未分类」。这是完成分布，不代表各分类的整体效率。",
  "taskAnalytics.definitions.history": "历史限制：升级前已完成的普通任务按数据库中真实的 completed_at 回填；重复任务的历史完成期次在升级前没有持久化，无法还原，也不会伪造回填。升级后的每次完成都会可靠落库。",
  "taskAnalytics.category.uncategorized": "未分类",
  "taskAnalytics.historyIncomplete": "不完整统计：本期存在无法还原的重复任务期次（自动推进、停机补偿跳期或主动改期），完成率与逾期率可能偏高。",
  "taskAnalytics.updatedAt": "更新于 {time}",

