  "onboarding.title.1": "认识 task_dock",
  "onboarding.body.1":
    "左侧导航按用途分区：任务、Agent、行动、剪贴板是日常高频页；应用、微件、工作流按需启用。窗口贴到屏幕边缘会自动收纳成胶囊，拖出即可恢复完整面板。",
  "onboarding.title.2": "完成第一个任务",
  "onboarding.body.2":
    "按 Ctrl+K 或点击左上角「新建任务」，一句话即可创建：支持自然语言时间（如「明天下午三点提醒我」）、重复规则与提前提醒。",
  "onboarding.title.3": "按需启用功能",
  "onboarding.body.3":
    "在「设置」里可以调整主题材质、快捷键、导航显隐与通知；微件、专注、工作流等能力默认就绪，无需额外开启。遇到问题随时到「帮助」页搜索。",
